result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "sokoban.py", "content": """"Minimal Sokoban engine plus an optimal BFS solver."""

from collections import deque

MOVES = {
    "u": (-1, 0),
    "d": (1, 0),
    "l": (0, -1),
    "r": (0, 1),
}

FLOOR = "-"
WALL = "#"
BOX = "$"
GOAL = "X"


def parse_level(text):
    """Parse a level string into a dict with walls, goals and start state."""
    rows = [line for line in text.strip("\n").split("\n")]
    walls, goals = set(), set()
    player = None
    boxes = frozenset()
    box_cells = set()
    for r, row in enumerate(rows):
        for c, ch in enumerate(row):
            pos = (r, c)
            if ch == WALL:
                walls.add(pos)
            elif ch == GOAL:
                goals.add(pos)
            elif ch == BOX:
                box_cells.add(pos)
            elif ch == "@":
                player = pos
            # '-' is plain floor; anything else is ignored.
    boxes = frozenset(box_cells)
    if player is None:
        raise ValueError("level has no player '@'")
    return {"walls": walls, "goals": frozenset(goals), "player": player, "boxes": boxes}


class Sokoban:
    def __init__(self, level_text):
        lvl = parse_level(level_text)
        self.walls = lvl["walls"]
        self.goals = lvl["goals"]
        self.player = lvl["player"]
        self.boxes = lvl["boxes"]

    def _cell(self, pos):
        return self.goals | self.boxes  # not used; placeholder

    def is_solved(self, boxes=None):
        boxes = self.boxes if boxes is None else boxes
        return boxes <= self.goals

    def step(self, move):
        """Apply a single move 'u'/'d'/'l'/'r' to the engine state."""
        dr, dc = MOVES[move]
        r, c = self.player
        target = (r + dr, c + dc)
        if target in self.walls:
            return False
        if target in self.boxes:
            beyond = (r + 2 * dr, c + 2 * dc)
            if beyond in self.walls or beyond in self.boxes:
                return False
            # pushes allowed onto floor/goal only (i.e., not into walls/boxes)
            self.boxes = frozenset((self.boxes - {target}) | {beyond})
        self.player = target
        return True

    def moves(self, move_str):
        """Apply each character of move_str; returns True iff all applied and solved."""
        for ch in move_str:
            if ch not in MOVES or not self.step(ch):
                return False
        return self.is_solved()


def _corner_deadlock(pos, walls, goals):
    """A box on a non-goal square in a corner can never be moved again usefully."""
    r, c = pos
    if pos in goals:
        return False
    up, down = (r - 1, c) in walls, (r + 1, c) in walls
    left, right = (r, c - 1) in walls, (r, c + 1) in walls
    return (up or down) and (left or right)


def solve(level_text, max_states=1_000_000):
    """BFS over (player, boxes) states.

    Returns the shortest move string, or None if unsolvable / exhausted.
    Prunes states where a box sits on a non-goal corner.
    """
    lvl = parse_level(level_text)
    walls, goals = lvl["walls"], lvl["goals"]
    start = (lvl["player"], lvl["boxes"])
    if lvl["boxes"] <= goals:
        return ""

    seen = {start}
    queue = deque([(start, "")])
    expanded = 0
    while queue:
        (player, boxes), path = queue.popleft()
        expanded += 1
        if expanded > max_states:
            return None
        pr, pc = player
        for move, (dr, dc) in MOVES.items():
            target = (pr + dr, pc + dc)
            if target in walls:
                continue
            if target in boxes:
                beyond = (pr + 2 * dr, pc + 2 * dc)
                if beyond in walls or beyond in boxes:
                    continue
                new_boxes = frozenset(boxes - {target} | {beyond})
                if _corner_deadlock(beyond, walls, goals):
                    continue
            else:
                new_boxes = boxes
            new_state = (target, new_boxes)
            if new_state in seen:
                continue
            new_path = path + move
            if new_boxes <= goals:
                return new_path
            seen.add(new_state)
            queue.append((new_state, new_path))
    return None
